<script lang="ts">
 import type{DesignSnapshot,DesignOperation}from'@schubert/contracts';
 import{selectionMoveOperations,applyOperations,parseMillimetres}from'@schubert/geometry';
 import{describeStudioIssue}from'./issues.ts';
 let{snapshot,selectedIds,disabled=false,onchange}:{snapshot:DesignSnapshot;selectedIds:string[];disabled?:boolean;onchange:(operations:DesignOperation[])=>void}=$props();
 let dx=$state('0'),dy=$state('0'),dz=$state('0'),error=$state('');
 function move(event:SubmitEvent){event.preventDefault();error='';try{const values=[dx,dy,dz].map(parseMillimetres);if(values.some(value=>value===null))throw Error('Alle drei Verschiebungen eindeutig in mm angeben.');const deltaWorld={xMm:values[0]!,yMm:values[1]!,zMm:values[2]!};if(!selectionMoveOperations(snapshot,selectedIds,deltaWorld).length)throw Error('In dieser Richtung ist keine Änderung möglich. Die Lage am zugehörigen Bezugselement bearbeiten.');const operations:DesignOperation[]=[{type:'move_selection',elementIds:[...selectedIds],deltaWorld}];applyOperations(snapshot,operations);onchange(operations);dx='0';dy='0';dz='0';}catch(problem){error=describeStudioIssue(snapshot,(problem as Error).message).message;}}
</script>
<form class="selection-move" onsubmit={move}><h3>Auswahl gemeinsam versetzen</h3><p>Werte im globalen Planbezug. Gemeinsame Wandknoten bewegen sich einmal; gebundene Öffnungen behalten ihren Wandbezug. Raumhöhen werden über das eigene Bodenhöhenmaß bearbeitet.</p><div><label>X (mm)<input aria-label="Auswahlversatz X (mm)" inputmode="decimal" bind:value={dx} required {disabled}/></label><label>Y (mm)<input aria-label="Auswahlversatz Y (mm)" inputmode="decimal" bind:value={dy} required {disabled}/></label><label>Z (mm)<input aria-label="Auswahlversatz Z (mm)" inputmode="decimal" bind:value={dz} required {disabled}/></label></div>{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="btn small" type="submit" {disabled}>Gesamte Auswahl versetzen</button></form>
<style>.selection-move{font-size:13px;line-height:1.65;padding:16px 0 22px;border-bottom:1px solid var(--line);margin-bottom:20px}.selection-move h3{font-size:14px;font-weight:600}.selection-move p{font-size:12px;color:var(--muted)}.selection-move>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.selection-move label{font-size:12px}.selection-move input{box-sizing:border-box;display:block;width:100%;min-height:44px;margin:7px 0 14px;padding:10px;font:inherit;font-size:14px;border:1px solid var(--line);border-radius:4px;background:var(--paper);color:var(--ink)}.selection-move .error{padding:12px;background:var(--danger-wash);color:var(--danger);border:1px solid var(--line);white-space:pre-wrap}@media(max-width:720px){.selection-move input,.selection-move button{min-height:48px;font-size:16px}}</style>
